ALTER TABLE "reward_branches" ADD CONSTRAINT "reward_branches_branch_id_branches_id_fk" FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
